 {key:'longcat-25',importance:'high',sourceDate:date,urls:[rows[4].url,rows[5].url],facts:'Read complete official changelog: version2026-11-02 explicitly announces LongCat-2.5; native visual understanding, agentic coding, long-horizon engineering and harness compatibility. Preview is separately dated2026-09-25.',limits:'Blog HTTP200 is only a27character JS shell, not factual verification. Parameter counts and benchmarks require the blog payload or another original; do not verify those numbers from changelog.'},
 {key:'suleyman-model-welfare-date',importance:'high',sourceDate:'2026-09-16',urls:[rows[6].url],facts:'Read original essay header and argument: dated16September2026, challenges model-welfare training and anthropomorphism, proposes industry evaluation and human control. His claims are his position, not an established proof of absent AI consciousness.',limits:'November2 Chinese roundup is a rediscovery, not a new essay. No verified new X timestamp. Preserve actual original date; do not count as November2 release.'},
 {key:'gpt62-mythos55-report',importance:'medium',sourceDate:date,urls:[rows[9].url],facts:'Read fullQbitAI article, author梦晨, original timestamp2026-11-02 12:28:53. It reports user routing observations and a transient frontend model name. Article explicitly doubts alleged HuggingFace weights.',limits:'No official launch announcement or verified leaked weights. Eligible only as attributed media report of unconfirmed observations, never new confirmed model release.'},
 {key:'sensenova-loop-original-date',importance:'high',sourceDate:'2026-10-30',urls:[rows[8].url],facts:'Read official model card, datedNews2026.10.30:~9B stored/~14.6B inference parameters,32distinct layers/56executions,24layers loop twice,hybrid linear/full attention,two-stream mHC,262144training sequence,Apache2.0. Technical reportTBD and Transformers publication details pending. MTP available;DSpark/DFlash2 training in progress.',limits:'Do not date model releaseNov1/Nov2 because of social reposts. No evidence for comparison to unannouncedOpenAI architectures. Do not call all runtime support generally released.'},
 {key:'official-news-freshness',importance:'medium',urls:rows.slice(0,4).map(r=>r.url),facts:'Read official OpenAIRSS latestOct30; Anthropic list latest dated entriesOct28 (page current-date header not article date); Google AI feed latestOct26; NVIDIA feed latestOct30. No newly datedNov2 article on these inspected surfaces.',limits:'Limited to observed feeds/lists; not proof of no announcement elsewhere. OriginalX andoEmbed access failed, web returned403; retain inaccessible state rather than no-news.'}
